def parse(tree):
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


def kthLargestInBst(tree, k):
    val, left, right = parse(tree)
    stack = []
    u = 0
    while stack or u != -1:
        while u != -1:
            stack.append(u)
            u = right[u]
        u = stack.pop()
        k -= 1
        if k == 0:
            return val[u]
        u = left[u]
    return -1
